sys_script_include.script:
var FetchEventDetailsUtils = Class.create();
FetchEventDetailsUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {


	eventdetails: function () {
		var eventID = this.getParameter('sysparm_eventID');

		var gr = new GlideRecord('x_1790139_event_ma_event_record');
		if (gr.get(eventID)) {

			var details = "Event Date: " + gr.getValue('x_event_date') +
				", Status: " + gr.getValue('x_status') + ", ID: " + gr.getValue('number') + ",isVip:" + gr.getValue('x_is_vip');
			return details;
		} else {
			return "Event not found.";
		}
	},

	type: 'FetchEventDetailsUtils'
});
